(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.ExpLogEquationLesson,num=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function decimal(x,digits){return x.toFixed(digits).replace('.','{,}');}
function guess(){const x=Number($('#exponent-guess').value),r=core.exponential(x);$('#exponent-guess-output').value=x.toFixed(3).replace('.',',');math($('#exponent-check'),`2^{${decimal(x,3)}}\\approx${decimal(r.left,6)}`);$('#exponent-feedback').innerHTML=`Selisih ruas kiri terhadap tiga sekitar <span data-tex="${decimal(r.residual,6)}"></span>. `+(r.residual<0?'Nilai ruas kiri masih lebih kecil dari tiga.':'Nilai ruas kiri lebih besar dari tiga.')+' Angka yang ditampilkan adalah pendekatan; solusi tepat tetap logaritma tiga pada basis dua.';}
$('#exponent-guess').addEventListener('input',guess);$('#use-rounded').addEventListener('click',()=>{$('#exponent-guess').value='1.585';guess();});guess();
const original='\\log_2(x-1)+\\log_2(x-3)=3';
const steps=[
{equation:original,prompt:'Apa domain persamaan semula?',choices:[{tex:'x>1',label:'Masukan lebih besar dari satu',wrong:'Argumen pertama memang positif, tetapi argumen kedua juga perlu positif. Periksa masukan dikurangi tiga.'},{tex:'x>3',label:'Masukan lebih besar dari tiga',correct:true},{tex:'x>0',label:'Masukan positif',wrong:'Yang harus positif adalah setiap argumen, bukan hanya masukannya. Masukan positif saja belum cukup.'}],result:'D=(3,\\infty)',reason:'Kedua argumen awal positif hanya ketika masukan lebih besar dari tiga.'},
{equation:original,prompt:'Di dalam domain awal, bagaimana kedua logaritma digabung?',choices:[{tex:'\\log_2(2x-4)=3',label:'Logaritma jumlah kedua argumen sama dengan tiga',wrong:'Jumlah logaritma menjadi logaritma hasil kali, bukan logaritma jumlah argumen.'},{tex:'\\log_2((x-1)(x-3))=3',label:'Logaritma hasil kali kedua argumen sama dengan tiga',correct:true},{tex:'(x-1)(x-3)=3',label:'Hasil kali kedua argumen sama dengan tiga',wrong:'Logaritma belum dapat dihilangkan dengan menyalin ruas kanan. Ubah hubungan logaritma ke bentuk pangkat.'}],result:'\\log_2((x-1)(x-3))=3',reason:'Aturan hasil kali berlaku karena masing-masing argumen positif pada domain yang sudah dicatat.'},
{equation:'\\log_2((x-1)(x-3))=3',prompt:'Apa bentuk pangkat yang setara pada domain awal?',choices:[{tex:'(x-1)(x-3)=8',label:'Hasil kali kedua argumen sama dengan delapan',correct:true},{tex:'(x-1)(x-3)=6',label:'Hasil kali kedua argumen sama dengan enam',wrong:'Basis dua dipangkatkan tiga menghasilkan delapan, bukan dua dikali tiga.'},{tex:'(x-1)(x-3)=3',label:'Hasil kali kedua argumen sama dengan tiga',wrong:'Logaritma menyatakan pangkat. Ruas argumen harus sama dengan dua pangkat tiga.'}],result:'(x-1)(x-3)=8',reason:'Logaritma berbasis dua bernilai tiga berarti argumennya sama dengan dua pangkat tiga.'},
{equation:'(x-1)(x-3)=8',prompt:'Faktorisasi mana yang memberikan kandidat persamaan aljabar ini?',choices:[{tex:'(x-1)(x-3)=0',label:'Masukan dikurangi satu kali masukan dikurangi tiga sama dengan nol',wrong:'Ruas kanan masih delapan. Kembangkan dahulu dan kurangi delapan pada kedua ruas.'},{tex:'(x-5)(x+1)=0',label:'Masukan dikurangi lima kali masukan ditambah satu sama dengan nol',correct:true},{tex:'(x+5)(x-1)=0',label:'Masukan ditambah lima kali masukan dikurangi satu sama dengan nol',wrong:'Periksa suku linear setelah kedua faktor dikalikan. Bentuk yang diperlukan mempunyai koefisien linear negatif empat.'}],result:'x=5\\quad\\text{atau}\\quad x=-1',reason:'Bentuk kuadratnya adalah kuadrat masukan dikurangi empat kali masukan dikurangi lima, sehingga diperoleh dua kandidat.'},
{equation:'x=5\\quad\\text{atau}\\quad x=-1',prompt:'Kandidat mana yang merupakan solusi persamaan semula?',choices:[{tex:'\\{-1,5\\}',label:'Kedua kandidat, negatif satu dan lima',wrong:'Negatif satu membuat kedua argumen awal negatif. Hasil kali yang positif tidak menyelamatkan dua logaritma yang tidak terdefinisi.'},{tex:'\\{5\\}',label:'Hanya lima',correct:true},{tex:'\\{-1\\}',label:'Hanya negatif satu',wrong:'Negatif satu berada di luar domain awal. Lima justru memenuhi kedua syarat argumen positif.'}],result:'S=\\{5\\}',reason:'Hanya lima berada dalam domain awal. Substitusinya memberi logaritma empat ditambah logaritma dua, yaitu tiga.'}
];let phase=0;
function renderStep(){if(phase>=steps.length){math($('#guided-equation'),'\\log_2 4+\\log_2 2=2+1=3');$('#guided-prompt').textContent='Selesai. Solusi lima memenuhi persamaan semula; kandidat negatif satu ditolak oleh domain awal.';$('#guided-choices').replaceChildren();return;}const step=steps[phase];math($('#guided-equation'),step.equation);$('#guided-prompt').textContent=step.prompt;$('#guided-choices').replaceChildren();for(const choice of step.choices){const button=document.createElement('button');button.type='button';button.setAttribute('aria-label',choice.label);math(button,choice.tex);button.addEventListener('click',()=>{const feedback=$('#guided-feedback');feedback.className='feedback '+(choice.correct?'correct':'incorrect');if(!choice.correct){feedback.textContent=choice.wrong;return;}feedback.textContent='Tepat. '+step.reason;const li=document.createElement('li'),formula=document.createElement('div'),reason=document.createElement('span');math(formula,step.result);reason.textContent=step.reason;li.append(formula,reason);$('#guided-history').append(li);phase++;renderStep();});$('#guided-choices').append(button);}}
$('#restart-steps').addEventListener('click',()=>{phase=0;$('#guided-history').replaceChildren();$('#guided-feedback').textContent='';renderStep();});renderStep();
const questions=[{tex:'2^{x+1}=16',prompt:'Tentukan nilai masukan yang memenuhi persamaan.',n:3,hint:'Enam belas adalah dua pangkat empat. Bandingkan pangkatnya.',why:'Pangkat masukan ditambah satu harus sama dengan empat. Jadi masukannya tiga.'},{tex:'\\log_3(x-2)=2',prompt:'Tentukan solusi yang memenuhi domain awal.',n:11,hint:'Domainnya masukan lebih besar dari dua. Ubah ke bentuk tiga pangkat dua.',why:'Masukan dikurangi dua sama dengan sembilan, sehingga masukannya sebelas dan memenuhi domain.'},{tex:'\\log_2 x+\\log_2(x-2)=3',prompt:'Tentukan satu-satunya solusi pada domain awal.',n:4,hint:'Domainnya masukan lebih besar dari dua. Hasil kali argumen sama dengan delapan.',why:'Persamaan hasil kali memberikan kandidat empat dan negatif dua. Hanya empat memenuhi kedua argumen positif.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis satu bilangan, misalnya 4.':'Belum tepat. Periksa bentuk pangkat dan syarat setiap argumen semula.');}));
const choices=[{tex:'5^x=-1',prompt:'Bagaimana himpunan solusi real persamaan ini?',options:['Hanya negatif satu.','Tidak ada solusi real.','Hanya nol.'],answer:1,why:'Lima pangkat bilangan real selalu positif. Ruas kiri tidak mungkin sama dengan negatif satu.'},{tex:original,prompt:'Mengapa kandidat negatif satu harus ditolak?',options:['Kedua argumen awal negatif, meskipun hasil kalinya positif.','Semua logaritma melarang keluaran negatif.','Persamaan kuadrat tidak boleh mempunyai dua kandidat.'],answer:0,why:'Syarat positif berlaku untuk masing-masing argumen logaritma awal. Kandidat itu bukan anggota domain persamaan semula.'},{tex:'2^x=3',prompt:'Manakah penulisan solusi tepat?',options:['Satu koma lima delapan lima tanpa tanda pendekatan.','Tiga dibagi dua.','Logaritma tiga pada basis dua.'],answer:2,why:'Logaritma tiga pada basis dua adalah nilai tepat. Satu koma lima delapan lima hanya pendekatan tiga desimal.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}">${o}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-exp-log-equation-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-exp-log-equation-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();